class SaveCareerPromptClass : public FEMenu
{
public:
  enum
  {
    START_SAVING_GLOBAL,
    SAVING_GLOBAL,
    START_SAVING_CAREER,
    SAVING_CAREER,
    START_SAVING_PHOTO,
    SAVING_PHOTO,
    SAVING_DONE,
    STATE_NONE
  };
